    public interface A2ABuilders {
        /**
         * A2A (camel-a2a)
         * Expose a route as an agent and call remote agents with the
         * Agent2Agent (A2A) protocol.
         * 
         * Category: ai
         * Since: 4.21
         * Maven coordinates: org.apache.camel:camel-a2a
         * 
         * @return the dsl builder for the headers' name.
         */
        default A2AHeaderNameBuilder a2a() {
            return A2AHeaderNameBuilder.INSTANCE;
        }
        /**
         * A2A (camel-a2a)
         * Expose a route as an agent and call remote agents with the
         * Agent2Agent (A2A) protocol.
         * 
         * Category: ai
         * Since: 4.21
         * Maven coordinates: org.apache.camel:camel-a2a
         * 
         * Syntax: <code>a2a:agentCardSource</code>
         * 
         * Path parameter: agentCardSource (required)
         * Where the agent card comes from: a JSON file on the classpath
         * (classpath:) or in the file system (file:), an http:// or https://
         * URL that the endpoint downloads the card from when it starts, or a
         * plain name, which is the agent name when no card gives one. A URL
         * that does not end with .json gets the path
         * /.well-known/agent-card.json. The consumer serves the card as its
         * own. The producer calls the URL that the card gives for
         * protocolBinding, or this URL without the well-known path when the
         * card gives none or when apiKey, bearerToken or oauthProfile is set.
         * 
         * @param path agentCardSource
         * @return the dsl builder
         */
        default A2AEndpointBuilder a2a(String path) {
            return A2AEndpointBuilderFactory.endpointBuilder("a2a", path);
        }
        /**
         * A2A (camel-a2a)
         * Expose a route as an agent and call remote agents with the
         * Agent2Agent (A2A) protocol.
         * 
         * Category: ai
         * Since: 4.21
         * Maven coordinates: org.apache.camel:camel-a2a
         * 
         * Syntax: <code>a2a:agentCardSource</code>
         * 
         * Path parameter: agentCardSource (required)
         * Where the agent card comes from: a JSON file on the classpath
         * (classpath:) or in the file system (file:), an http:// or https://
         * URL that the endpoint downloads the card from when it starts, or a
         * plain name, which is the agent name when no card gives one. A URL
         * that does not end with .json gets the path
         * /.well-known/agent-card.json. The consumer serves the card as its
         * own. The producer calls the URL that the card gives for
         * protocolBinding, or this URL without the well-known path when the
         * card gives none or when apiKey, bearerToken or oauthProfile is set.
         * 
         * @param componentName to use a custom component name for the endpoint
         * instead of the default name
         * @param path agentCardSource
         * @return the dsl builder
         */
        default A2AEndpointBuilder a2a(String componentName, String path) {
            return A2AEndpointBuilderFactory.endpointBuilder(componentName, path);
        }

    }
