    static A2AEndpointBuilder endpointBuilder(String componentName, String path) {
        class A2AEndpointBuilderImpl extends AbstractEndpointBuilder implements A2AEndpointBuilder, AdvancedA2AEndpointBuilder {
            public A2AEndpointBuilderImpl(String path) {
                super(componentName, path);
            }
        }
        return new A2AEndpointBuilderImpl(path);
    }
